    /** 화면초기화 **/
    scwin.fnInitial = function() {

    };

    /** 부모창에서 탭클릭시.. **/
    scwin.init = function() {

    	var reloadFlag = sessionStorage.getItem("PR0000_reloadFlag");
//		if(scwin.searchFalg && reloadFlag == "N") return;

    	scwin.param = $p.getFrame().getParentFrame().getObj("dsPyrqInfo");
    	dsRegSearch.setJSON( scwin.param.getJSON() );

    	scwin.fnSelectItemiRegList(scwin.param.getJSON());
    };


    /************************************************************************************
     *  [3] 사용자 정의함수 함수 
     ************************************************************************************/
    //내역조회
	scwin.fnSelectItemiRegList = function(sData) {

		scwin.searchFalg = true;
		sessionStorage.setItem("PR0000_reloadFlag", "N");

		dsRegSearch.set( "siteCd" , sData.siteCd );
		dsRegSearch.set( "pyrqDt" , sData.pyrqDt );
		dsRegSearch.set( "pyrqSeq" , sData.pyrqSeq );
		scwin.svcId = "selectItemiRegList";

		ajaxLib.ajax("/pr/pr0005/PR00050004P/selectItemiRegList", {
            mode		: "asynchronous",
            method 		: "Post",
            requestData	: dsRegSearch.getJSON(),
			callback	: "fnCallback",	
            errCallback	: "fnErrCallback"
        });
	};

    /************************************************************************************
     *  [4] Callback 함수 
     ************************************************************************************/
    /** 오류시 처리 **/
	scwin.fnErrCallback = function(result, e) {


	}

    /** 정상시 후처리 **/
   /*scwin.fnCallback = function(result, e) {

