    /************************************************************************************
     *  [5] Event 함수 
     ************************************************************************************/      

    //전체펼침
	scwin.btnAllExp_onclick = function() {
		grdItemiRegList.spanAll(true);
	};

	//전체접기
	scwin.btnAllFold_onclick = function() {
		grdItemiRegList.spanAll(2);
	};

	//저장버튼
	scwin.btnSave_onclick = function() {
		var list = new Array();
		var saveList = dsItemiRegList.getDeletedIndex();
		if(saveList.length < 1){
			 com.showMessage("SCA0007");
			 return false;
		}
		if(confirm("삭제하시겠습니까?")){
			for(var i=0; i<saveList.length; i++){
				list.push(dsItemiRegList.getRowJSON( saveList[i] ));
			}

			scwin.svcId = "saveItemiReg";

			//서비스 호출
			ajaxLib.ajax("/pr/pr0005/PR00050004P/saveItemiRegList", {
	            mode : "asynchronous"
						, requestData : {
							tprPurcPyrqItemiVOList : list,
							tprPurcBilldVO         : dsRegSearch.getJSON()
						},
				callback	: "fnCallback",	
	            errCallback	: "fnErrCallback"
	        });
	    }
	};
	//행삭제버튼
	scwin.btnDelRow_onclick = function() {

		var cnt = 0;
		for(var i=0; i<scwin.searchRowCnt; i++){
			if(dsItemiRegList.getCellData(i , "chk") == 1){
				dsItemiRegList.deleteRow(i);
				cnt++
			}
		}
		if(cnt == 0){
			com.showMessage("SCA0011", "", "", ""); // 삭제하실 항목을 선택하세요.
			return;
		}
    };

	//엑셀다운 
	scwin.btnExcelDwn_onclick = function() {
		/*
		var options = {
			fileName : "SubSitedItemiList.xlsx"
		};

		grdItemiRegList.advancedExcelDownload(options); */

		var infoArr = {};
        var fileNm = "구매청구 내역등록.xlsx";
        var options = { fileName : fileNm };
        com.gridDataDownLoad(grdItemiRegList, options, infoArr);
	};

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('grdItemiRegList_totActbgtAmt').innerText == '455,369,600';
	}
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btnAllFold').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btnAllExp').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
